// All API calls go through the Express gateway on :4000
const BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:4000/api';

function getToken() {
  return localStorage.getItem('access_token');
}

async function request(endpoint, options = {}) {
  const token = getToken();
  const headers = {
    'Content-Type': 'application/json',
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
    ...options.headers,
  };

  const res = await fetch(`${BASE_URL}${endpoint}`, { ...options, headers });

  // Auto-handle 401 — clear token and redirect to login
  if (res.status === 401) {
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
    window.location.href = '/login';
    return;
  }

  const data = await res.json().catch(() => ({}));

  if (!res.ok) {
    const message = data.detail || data.error || JSON.stringify(data);
    throw new Error(message);
  }

  return data;
}

// ─── Auth ─────────────────────────────────────────────────────────────────────
export const auth = {
  register: (data) => request('/auth/register/', { method: 'POST', body: JSON.stringify(data) }),
  login: async (credentials) => {
    const data = await request('/auth/login/', { method: 'POST', body: JSON.stringify(credentials) });
    localStorage.setItem('access_token', data.access);
    localStorage.setItem('refresh_token', data.refresh);
    return data;
  },
  logout: () => {
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
  },
  me: () => request('/auth/me/'),
};

// ─── Projects ─────────────────────────────────────────────────────────────────
export const projects = {
  list: (search = '') => request(`/projects/${search ? `?search=${search}` : ''}`),
  get: (id) => request(`/projects/${id}/`),
  create: (data) => request('/projects/', { method: 'POST', body: JSON.stringify(data) }),
  update: (id, data) => request(`/projects/${id}/`, { method: 'PATCH', body: JSON.stringify(data) }),
  delete: (id) => request(`/projects/${id}/`, { method: 'DELETE' }),
};

// ─── Tasks ────────────────────────────────────────────────────────────────────
export const tasks = {
  list: (filters = {}) => {
    const params = new URLSearchParams(filters).toString();
    return request(`/tasks/${params ? `?${params}` : ''}`);
  },
  get: (id) => request(`/tasks/${id}/`),
  create: (data) => request('/tasks/', { method: 'POST', body: JSON.stringify(data) }),
  update: (id, data) => request(`/tasks/${id}/`, { method: 'PATCH', body: JSON.stringify(data) }),
  delete: (id) => request(`/tasks/${id}/`, { method: 'DELETE' }),
};
